"""Proof material assembly and validation.

A successful proof job yields five non-sensitive, persistable materials:

* ``manifest``        – binds the claim (model, quantization, q_score,
                        statement digest) to every other material and to
                        EZKL 23.0.5 via SHA-256 digests;
* ``proof``           – the EZKL proof JSON (includes the public
                        ``instances``; blinding makes each proof unique);
* ``verification_key``– the deterministic EZKL verification key (binary);
* ``settings``        – the EZKL circuit settings JSON;
* ``instances``       – the public instances only (a single public output
                        felt); private inputs are never part of instances.

Raw features, per-feature encodings, and witnesses are never placed in any
material, manifest, response, log, or exception.
"""

import base64
from hashlib import sha256
import json

from .statements import QUANTIZATION_ID, ROUNDING, SCALE, _jcs_serialize
from .backend import EZKL_VERSION, PROOF_SCALE

MANIFEST_VERSION = "1.0"
# The public circuit output and q_score lie on the same Q16 grid; EZKL's
# re-quantization can shift the result by at most one fixed-point unit.
Q_SCORE_TOLERANCE = 1

_HEX_CHARS = set("0123456789abcdef")


class MaterialError(ValueError):
    """A material failed structural, digest, or model-mapping validation."""

    def __init__(self, code: str = "invalid_proof_material"):
        super().__init__(code)
        self.code = code


def digest_bytes(data: bytes) -> str:
    return sha256(data).hexdigest()


def digest_json(value) -> str:
    """Digest over the RFC 8785 canonical form of a JSON value."""
    return sha256(_jcs_serialize(value).encode("utf-8")).hexdigest()


def b64_encode(data: bytes) -> str:
    return base64.b64encode(data).decode("ascii")


def b64_decode(value: str) -> bytes:
    if not isinstance(value, str) or not value:
        raise MaterialError
    try:
        return base64.b64decode(value.encode("ascii"), validate=True)
    except Exception:
        raise MaterialError from None


def _is_hex64(value) -> bool:
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(ch in _HEX_CHARS for ch in value)
    )


def decode_output_felt(instances) -> int:
    if (
        not isinstance(instances, list)
        or len(instances) != 1
        or not isinstance(instances[0], list)
        or len(instances[0]) != 1
        or not _is_hex64(instances[0][0])
    ):
        raise MaterialError
    return int.from_bytes(bytes.fromhex(instances[0][0])[::-1], "big")


def parse_proof(proof_bytes: bytes) -> dict:
    """Parse and structurally validate an EZKL proof JSON document."""
    try:
        doc = json.loads(proof_bytes)
    except (UnicodeDecodeError, ValueError):
        raise MaterialError from None
    if not isinstance(doc, dict):
        raise MaterialError
    if not isinstance(doc.get("proof"), list) or not doc["proof"]:
        raise MaterialError
    if not all(isinstance(byte, int) and 0 <= byte <= 255
               for byte in doc["proof"]):
        raise MaterialError
    if not isinstance(doc.get("hex_proof"), str) or not doc["hex_proof"]:
        raise MaterialError
    if doc.get("version") != EZKL_VERSION:
        raise MaterialError
    instances = doc.get("instances")
    # Shape-only validation here; felt decoding is done separately.
    decode_output_felt(instances)
    return doc


def parse_settings(settings_bytes: bytes) -> dict:
    """Parse and structurally validate EZKL settings, returning normalized copy."""
    try:
        doc = json.loads(settings_bytes)
    except (UnicodeDecodeError, ValueError):
        raise MaterialError from None
    if not isinstance(doc, dict) or not isinstance(doc.get("run_args"), dict):
        raise MaterialError
    run = doc["run_args"]
    if (
        run.get("input_visibility") != "Private"
        or run.get("output_visibility") != "Public"
        or doc.get("model_input_scales") != [PROOF_SCALE]
        or doc.get("model_output_scales") != [PROOF_SCALE]
        or doc.get("model_instance_shapes") != [[1, 1]]
        or doc.get("version") != EZKL_VERSION
    ):
        raise MaterialError
    normalized = dict(doc)
    # The timestamp is the one per-build, non-semantic settings field.
    normalized.pop("timestamp", None)
    return normalized


def build_manifest(*, model_sha256: str, q_score: int, statement_sha256: str,
                   output_felt: int, proof_bytes: bytes, settings_bytes: bytes,
                   vk_bytes: bytes, instances) -> dict:
    """Assemble the digest-binding manifest for a freshly generated proof."""
    return {
        "manifest_version": MANIFEST_VERSION,
        "model_id": "device-health-v1",
        "model_sha256": model_sha256,
        "quantization_id": QUANTIZATION_ID,
        "q_score": q_score,
        "scale": SCALE,
        "rounding": ROUNDING,
        "statement_sha256": statement_sha256,
        "ezkl_version": EZKL_VERSION,
        "circuit": {
            "input_visibility": "Private",
            "output_visibility": "Public",
            "output_scale": PROOF_SCALE,
        },
        "public_output": {"felt": output_felt, "scale": PROOF_SCALE},
        "instances_sha256": digest_json(instances),
        "materials": {
            "proof_sha256": digest_bytes(proof_bytes),
            "verification_key_sha256": digest_bytes(vk_bytes),
            "settings_sha256": digest_bytes(settings_bytes),
        },
    }


def statement_digest_from_manifest(manifest: dict) -> str:
    """Recompute the statement digest bound inside a manifest.

    Mirrors statements.build_statement: the digest preimage is exactly the
    claim fields, JCS-canonicalized.
    """
    body = {
        "model_id": manifest["model_id"],
        "model_sha256": manifest["model_sha256"],
        "quantization_id": manifest["quantization_id"],
        "q_score": manifest["q_score"],
        "scale": manifest["scale"],
        "rounding": manifest["rounding"],
    }
    return digest_json(body)


def validate_manifest_shape(manifest) -> dict:
    """Type-check the manifest enough to safely read its binding fields."""
    if not isinstance(manifest, dict):
        raise MaterialError
    required_str = {
        "manifest_version", "model_id", "model_sha256", "quantization_id",
        "statement_sha256", "ezkl_version",
    }
    for key in required_str:
        if not isinstance(manifest.get(key), str):
            raise MaterialError
    for key in ("q_score", "scale"):
        value = manifest.get(key)
        if not isinstance(value, int) or isinstance(value, bool):
            raise MaterialError
    if not isinstance(manifest.get("rounding"), str):
        raise MaterialError
    circuit = manifest.get("circuit")
    output = manifest.get("public_output")
    materials = manifest.get("materials")
    if not isinstance(circuit, dict) or not isinstance(output, dict) \
            or not isinstance(materials, dict):
        raise MaterialError
    if (
        circuit.get("input_visibility") != "Private"
        or circuit.get("output_visibility") != "Public"
        or circuit.get("output_scale") != PROOF_SCALE
        or output.get("scale") != PROOF_SCALE
        or not isinstance(output.get("felt"), int)
    ):
        raise MaterialError
    for key in ("proof_sha256", "verification_key_sha256", "settings_sha256"):
        if not _is_hex64(materials.get(key)):
            raise MaterialError
    if not _is_hex64(manifest.get("instances_sha256")):
        raise MaterialError
    if manifest["manifest_version"] != MANIFEST_VERSION:
        raise MaterialError
    if manifest["ezkl_version"] != EZKL_VERSION:
        raise MaterialError
    # The semantic interpretation of the public output is pinned to the one
    # quantization scheme the circuit was built for; a claimant cannot relabel
    # a genuine proof as belonging to a different scheme (even though it could
    # recompute the self-consistent statement digest).
    if manifest["model_id"] != "device-health-v1":
        raise MaterialError
    if manifest["quantization_id"] != QUANTIZATION_ID:
        raise MaterialError
    if manifest["scale"] != SCALE or manifest["rounding"] != ROUNDING:
        raise MaterialError
    if not _is_hex64(manifest["model_sha256"]):
        raise MaterialError
    return manifest


def bind_materials(*, manifest: dict, proof_bytes: bytes, settings_bytes: bytes,
                   vk_bytes: bytes) -> dict:
    """Validate structure and all digest bindings of supplied materials.

    Returns ``{"instances": ..., "output_felt": ..., "settings_normalized": ...}``
    on success; raises MaterialError("invalid_proof_material") otherwise.
    Cryptographic EZKL verification and the trusted model mapping happen in
    the caller (they need the backend).
    """
    validate_manifest_shape(manifest)
    parse_settings(settings_bytes)  # structural only
    proof_doc = parse_proof(proof_bytes)
    instances = proof_doc["instances"]
    output_felt = decode_output_felt(instances)

    materials = manifest["materials"]
    if materials["proof_sha256"] != digest_bytes(proof_bytes):
        raise MaterialError
    if materials["settings_sha256"] != digest_bytes(settings_bytes):
        raise MaterialError
    if materials["verification_key_sha256"] != digest_bytes(vk_bytes):
        raise MaterialError
    if manifest["instances_sha256"] != digest_json(instances):
        raise MaterialError
    if output_felt != manifest["public_output"]["felt"]:
        raise MaterialError
    if abs(output_felt - manifest["q_score"]) > Q_SCORE_TOLERANCE:
        raise MaterialError
    if statement_digest_from_manifest(manifest) != manifest["statement_sha256"]:
        raise MaterialError
    settings_normalized = parse_settings(settings_bytes)
    return {
        "instances": instances,
        "output_felt": output_felt,
        "settings_normalized": settings_normalized,
    }


def settings_without_timestamp(settings_bytes: bytes) -> dict:
    """Normalized (timestamp-free) settings for the trusted model mapping."""
    return parse_settings(settings_bytes)

from fastapi import FastAPI, HTTPException
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, ConfigDict

from .audit import AuditError, audit_model
from .backend import ProofBackendError
from .jobs import JobError, get_manager
from .proof_materials import MaterialError
from .scoring import MODEL_ID, ROOT, ScoreRequest, ScoreResponse, model_info, score, session
from .statements import QuantizationError, StatementResponse, build_statement


app = FastAPI(title="Device health scores", version="0.1.0")


def _unavailable() -> HTTPException:
    return HTTPException(status_code=503, detail="model_unavailable")


@app.get("/", response_class=HTMLResponse, include_in_schema=False)
def home():
    return (ROOT / "static" / "index.html").read_text(encoding="utf-8")


@app.get("/healthz")
def health():
    try:
        session()
    except AuditError:
        raise _unavailable() from None
    return {"status": "ok", "engine": "onnxruntime", "mode": "ordinary-inference"}


@app.get("/models")
def models():
    try:
        return {"items": [model_info()]}
    except AuditError:
        raise _unavailable() from None


@app.get("/models/{model_id}")
def get_model(model_id: str):
    if model_id != MODEL_ID:
        raise HTTPException(status_code=404, detail="Unknown model")
    try:
        return model_info()
    except AuditError:
        raise _unavailable() from None


@app.get("/models/{model_id}/integrity")
def model_integrity(model_id: str):
    if model_id != MODEL_ID:
        raise HTTPException(status_code=404, detail="Unknown model")
    try:
        return audit_model(model_id)
    except AuditError:
        raise _unavailable() from None


@app.post("/score", response_model=ScoreResponse)
def create_score(request: ScoreRequest):
    try:
        return score(request)
    except KeyError:
        raise HTTPException(status_code=404, detail="Unknown model") from None
    except AuditError:
        raise _unavailable() from None


@app.post("/statements", response_model=StatementResponse)
def create_statement(request: ScoreRequest):
    try:
        return build_statement(request)
    except KeyError:
        raise HTTPException(status_code=404, detail="Unknown model") from None
    except QuantizationError as exc:
        raise HTTPException(status_code=422, detail=exc.code) from None
    except AuditError:
        raise _unavailable() from None


# -- asynchronous local CPU proof jobs -------------------------------------

_CLAIM_FIELDS = (
    "model_id", "model_sha256", "quantization_id", "q_score", "scale",
    "rounding", "statement_sha256", "ezkl_version",
)


def _claim(record: dict) -> dict:
    return {key: record[key] for key in _CLAIM_FIELDS}


def _job_view(record: dict) -> dict:
    """Public job view. Never includes features, encodings, or witnesses."""
    view = {
        "job_id": record["job_id"],
        "status": record["status"],
        "error_code": record.get("error_code"),
        "created_at": record.get("created_at"),
        "started_at": record.get("started_at"),
        "finished_at": record.get("finished_at"),
        **_claim(record),
    }
    if "materials" in record:
        view["materials"] = record["materials"]
    return view


class ProofVerificationRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")

    manifest: str
    proof: str
    verification_key: str
    settings: str


@app.post("/proof-jobs", status_code=202)
def create_proof_job(request: ScoreRequest):
    manager = get_manager()
    try:
        record = manager.submit(request)
    except KeyError:
        raise HTTPException(status_code=404, detail="Unknown model") from None
    except QuantizationError as exc:
        raise HTTPException(status_code=422, detail=exc.code) from None
    except AuditError:
        raise _unavailable() from None
    except ProofBackendError as exc:
        raise HTTPException(status_code=503, detail=exc.code) from None
    return {
        "job_id": record["job_id"],
        "status": record["status"],
        "queued": record["status"] == "queued",
        **_claim(record),
    }


@app.get("/proof-jobs/{job_id}")
def get_proof_job(job_id: str):
    record = get_manager().get(job_id)
    if record is None:
        raise HTTPException(status_code=404, detail="proof_job_not_found")
    return _job_view(record)


@app.delete("/proof-jobs/{job_id}")
def cancel_proof_job(job_id: str):
    try:
        record = get_manager().cancel(job_id)
    except JobError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.code) from None
    return _job_view(record)


@app.post("/proof-verifications")
def verify_proof(request: ProofVerificationRequest):
    manager = get_manager()
    try:
        return manager.verify_payload(request.model_dump())
    except MaterialError:
        raise HTTPException(status_code=422, detail="invalid_proof_material") from None
    except ProofBackendError as exc:
        raise HTTPException(status_code=503, detail=exc.code) from None

"""Fixed-model integrity audit for the bundled demonstration model.

The audit enforces the release contract for the single supported model
before any ordinary inference is served: the manifest must parse, have
correctly typed fields, and match the pinned release values; the ONNX
artifact must match the pinned SHA-256, pass the ONNX checker, and expose
exactly the expected inputs, outputs, operators, and initializers; and the
model must reproduce the pinned reference scores on CPU. The service only
ever runs ordinary inference; no zero-knowledge proofs are generated or
claimed anywhere in this audit.
"""

import copy
from hashlib import sha256
import json
from pathlib import Path
import threading

import numpy as np
import onnx
from onnx import numpy_helper
import onnxruntime as ort


ROOT = Path(__file__).resolve().parent.parent
MODEL_PATH = ROOT / "models" / "device-health-v1.onnx"
MANIFEST_PATH = ROOT / "models" / "device-health-v1.json"
MODEL_ID = "device-health-v1"

KNOWN_FEATURES = ("temperature", "vibration", "current", "runtime")
RELEASE_SHA256 = "4bf74b33ef32fe70aa57dcf5bd096b560d81af0c7eb0cb4378922f89ac66db8e"

EXPECTED_MANIFEST = {
    "id": MODEL_ID,
    "version": "1.0.0",
    "description": "Synthetic normalized device load score; not a diagnostic model.",
    "feature_order": ["temperature", "vibration", "current", "runtime"],
    "feature_range": [0.0, 1.0],
    "score_range": [0.1, 1.0],
    "score_direction": "higher-means-more-load",
    "input_shape": [1, 4],
    "output_shape": [1, 1],
    "onnx_opset": 13,
    "onnx_ir_version": 8,
    "sha256": RELEASE_SHA256,
}

EXPECTED_INITIALIZERS = {
    "weights": ([4, 1], [0.25, 0.25, 0.25, 0.15]),
    "bias": ([1], [0.1]),
}

REFERENCE_INPUTS = {
    "zeros": [0.0, 0.0, 0.0, 0.0],
    "sample": [0.2, 0.3, 0.4, 0.5],
    "ones": [1.0, 1.0, 1.0, 1.0],
}
REFERENCE_SCORES = {"zeros": 0.1, "sample": 0.4, "ones": 1.0}
REFERENCE_TOLERANCE = 1e-6

AUDIT_CHECKS = ["manifest", "sha256", "onnx_structure", "initializers", "reference_inference"]

_audit_lock = threading.Lock()
_session_lock = threading.Lock()
_sessions: dict = {}


class AuditError(Exception):
    """Audit failure carrying a stable, non-sensitive error code."""

    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def audit_model(model_id: str = MODEL_ID) -> dict:
    """Run the full audit and return the public report. Raises AuditError."""
    report, _manifest, _session = _run_audit(model_id)
    return report


def audited_artifacts(model_id: str = MODEL_ID):
    """Run the full audit; return (manifest copy, inference session)."""
    _report, manifest, session = _run_audit(model_id)
    return manifest, session


def _run_audit(model_id: str):
    if model_id != MODEL_ID:
        raise AuditError("unknown_model")
    # Serialize audits so concurrent callers only ever observe complete results.
    with _audit_lock:
        manifest = _load_manifest()
        model_bytes = _read_bytes(MODEL_PATH, "model_missing")
        digest = sha256(model_bytes).hexdigest()
        if digest != manifest["sha256"]:
            raise AuditError("model_digest_mismatch")
        _check_onnx(model_bytes, manifest)
        session = _session_for(digest, model_bytes)
        scores = _reference_scores(session)
        report = {
            "model_id": manifest["id"],
            "version": manifest["version"],
            "status": "ok",
            "mode": "ordinary-inference",
            "sha256": digest,
            "onnx_opset": manifest["onnx_opset"],
            "onnx_ir_version": manifest["onnx_ir_version"],
            "checks": list(AUDIT_CHECKS),
            "reference_scores": scores,
        }
        return report, copy.deepcopy(manifest), session


def _read_bytes(path: Path, code: str) -> bytes:
    try:
        return path.read_bytes()
    except OSError:
        raise AuditError(code) from None


def _load_manifest() -> dict:
    raw = _read_bytes(MANIFEST_PATH, "manifest_missing")
    try:
        data = json.loads(raw)
    except (UnicodeDecodeError, ValueError):
        raise AuditError("manifest_invalid_json") from None
    return _validate_manifest(data)


def _is_int(value) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_number(value) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _validate_manifest(data) -> dict:
    if not isinstance(data, dict):
        raise AuditError("manifest_invalid_type")
    for key in ("id", "version", "description", "score_direction", "sha256"):
        if not isinstance(data.get(key), str):
            raise AuditError("manifest_invalid_type")
    feature_order = data.get("feature_order")
    if not isinstance(feature_order, list) or not all(
        isinstance(feature, str) for feature in feature_order
    ):
        raise AuditError("manifest_invalid_type")
    for key in ("feature_range", "score_range"):
        value = data.get(key)
        if (
            not isinstance(value, list)
            or len(value) != 2
            or not all(_is_number(bound) for bound in value)
        ):
            raise AuditError("manifest_invalid_type")
    for key in ("input_shape", "output_shape"):
        value = data.get(key)
        if (
            not isinstance(value, list)
            or not value
            or not all(_is_int(dim) for dim in value)
        ):
            raise AuditError("manifest_invalid_type")
    for key in ("onnx_opset", "onnx_ir_version"):
        if not _is_int(data.get(key)):
            raise AuditError("manifest_invalid_type")
    if len(set(feature_order)) != len(feature_order):
        raise AuditError("manifest_duplicate_feature")
    if any(feature not in KNOWN_FEATURES for feature in feature_order):
        raise AuditError("manifest_unknown_feature")
    for key, expected in EXPECTED_MANIFEST.items():
        if data.get(key) != expected:
            raise AuditError("manifest_contract_mismatch")
    return data


def _check_value_info(value_info, name: str, shape: list, code: str) -> None:
    type_proto = value_info.type
    if not type_proto.HasField("tensor_type"):
        raise AuditError(code)
    tensor = type_proto.tensor_type
    if (
        value_info.name != name
        or tensor.elem_type != onnx.TensorProto.FLOAT
        or not tensor.HasField("shape")
    ):
        raise AuditError(code)
    dims = []
    for dim in tensor.shape.dim:
        if not dim.HasField("dim_value"):
            raise AuditError(code)
        dims.append(dim.dim_value)
    if dims != list(shape):
        raise AuditError(code)


def _check_onnx(model_bytes: bytes, manifest: dict) -> None:
    try:
        model = onnx.load_model_from_string(model_bytes)
    except Exception:
        raise AuditError("model_unparseable") from None
    try:
        onnx.checker.check_model(model)
    except Exception:
        raise AuditError("model_checker_failed") from None
    if model.ir_version != manifest["onnx_ir_version"]:
        raise AuditError("model_ir_mismatch")
    opsets = [(opset.domain or "", opset.version) for opset in model.opset_import]
    if opsets != [("", manifest["onnx_opset"])]:
        raise AuditError("model_opset_mismatch")
    graph = model.graph
    initializer_names = {init.name for init in graph.initializer}
    inputs = [value for value in graph.input if value.name not in initializer_names]
    if len(inputs) != 1:
        raise AuditError("model_input_mismatch")
    _check_value_info(inputs[0], "features", manifest["input_shape"], "model_input_mismatch")
    outputs = list(graph.output)
    if len(outputs) != 1:
        raise AuditError("model_output_mismatch")
    _check_value_info(outputs[0], "score", manifest["output_shape"], "model_output_mismatch")
    operators = sorted(node.op_type for node in graph.node)
    if operators != ["Add", "MatMul"] or any(
        node.domain not in ("", "ai.onnx") for node in graph.node
    ):
        raise AuditError("model_operator_mismatch")
    initializers = {init.name: init for init in graph.initializer}
    if set(initializers) != set(EXPECTED_INITIALIZERS):
        raise AuditError("model_initializer_mismatch")
    for name, (shape, values) in EXPECTED_INITIALIZERS.items():
        try:
            array = numpy_helper.to_array(initializers[name])
        except Exception:
            raise AuditError("model_initializer_mismatch") from None
        if (
            array.dtype != np.float32
            or list(array.shape) != list(shape)
            or not np.allclose(
                array.reshape(-1),
                np.asarray(values, dtype=np.float32),
                rtol=0,
                atol=REFERENCE_TOLERANCE,
            )
        ):
            raise AuditError("model_initializer_mismatch")


def _session_for(digest: str, model_bytes: bytes) -> ort.InferenceSession:
    # Keyed by the audited digest, so a file replaced in-process can never be
    # served from a stale cached session.
    with _session_lock:
        session = _sessions.get(digest)
        if session is None:
            options = ort.SessionOptions()
            options.intra_op_num_threads = 1
            options.inter_op_num_threads = 1
            try:
                session = ort.InferenceSession(
                    model_bytes, sess_options=options, providers=["CPUExecutionProvider"]
                )
            except Exception:
                raise AuditError("model_session_failed") from None
            _sessions.clear()
            _sessions[digest] = session
        return session


def _reference_scores(session: ort.InferenceSession) -> dict:
    scores = {}
    for label, values in REFERENCE_INPUTS.items():
        features = np.asarray([values], dtype=np.float32)
        try:
            output = session.run(["score"], {"features": features})[0]
        except Exception:
            raise AuditError("reference_inference_failed") from None
        scores[label] = float(output[0, 0])
    for label, expected in REFERENCE_SCORES.items():
        if abs(scores[label] - expected) > REFERENCE_TOLERANCE:
            raise AuditError("reference_inference_mismatch")
    return scores

